package com.example.domain.model.i18n

/** Machine translated draft; religious and linguistic review pending. */
internal object DuaSwDraft1 {
    val MAP: Map<String, DuaText> = mapOf(
        "dua_bismillah_la_yadurru" to DuaText("Ulinzi dhidi ya Madhara Yote", "Kwa jina la Mwenyezi Mungu ambaye hakuna kitakachodhuru kwa jina lake ardhini wala mbinguni, naye ni Mwenye kusikia, Mjuzi wa yote.", "Mara tatu kila asubuhi na jioni.", "Yeyote atakayesema mara tatu asubuhi na jioni, hakuna kitakachomdhuru."),
        "dua_raditu_billahi" to DuaText("Kutosheka na Mwenyezi Mungu kuwa ni Mola Mlezi", "Nimeridhika na Mwenyezi Mungu kuwa ni Mola wangu Mlezi, na Uislamu ndio dini yangu na Muhammad ﷺ kama Mtume wangu.", "Mara tatu asubuhi na jioni.", "Inakuwa ni haki kwa Mwenyezi Mungu kumridhia Siku ya Kiyama."),
        "dua_hasbiyallah" to DuaText("Hasbiyallah (Mwenyezi Mungu anatosha)", "Mwenyezi Mungu ananitosheleza; hakuna mungu ila Yeye. Kwake ninamtegemea, naye ni Mola Mlezi wa Arshi Kuu.", "Mara saba asubuhi na jioni.", "Aya ya Quran; Mwenyezi Mungu anatosha dhidi ya wasiwasi wa dunia na Akhera."),
        "dua_subhanallah_wa_bihamdihi" to DuaText("SubhanAllahi wa bihamdihi", "Ametakasika Mwenyezi Mungu na sifa njema zote ni zake.", "Mara mia kwa siku.", "Yeyote anayesema hivyo mara mia kwa siku atasamehewa dhambi zake, hata kama ni kama povu la bahari."),
        "dua_tahleel_100" to DuaText("La ilaha illallahu wahdahu", "Hapana apasae kuabudiwa kwa haki isipokuwa Mwenyezi Mungu, peke yake, asiye na mshirika. Ufalme ni wake, na sifa njema ni zake, na Yeye ni Muweza wa kila kitu.", "Fadhila kubwa ya kusema mara mia moja kwa siku.", "Malipo ya kuwaacha huru watumwa kumi, mema mia yaliyoandikwa, madhambi mia yaliyofutwa, na ulinzi kutoka kwa Shetani hadi jioni."),
        "dua_leaving_mosque" to DuaText("Akitoka Msikitini", "Ewe Mwenyezi Mungu, nakuomba fadhila zako.", "Wakati wa kutoka nje ya msikiti kwa mguu wa kushoto.", "Kuomba fadhila na riziki ya Mwenyezi Mungu wakati wa kutoka msikitini."),
        "dua_after_adhan" to DuaText("Baada ya Adhana", "Ewe Mwenyezi Mungu, Mola wa mwito huu mkamilifu na dua inayokaribia kusimamishwa, mpe Muhammad ﷺ al-Wasilah na wema, na umnyanyue kwenye Sifa njema uliyomuahidi.", "Baada ya adhana kukamilika.", "Atakayesema hivi atapewa uombezi wa Mtume ﷺ siku ya kiama."),
        "dua_after_salah_istighfar" to DuaText("Baada ya Fard Salah", "Naomba msamaha kwa Mwenyezi Mungu (mara 3). Ewe Mwenyezi Mungu, Wewe ni Salam na kutoka Kwako kuna amani. Umebarikiwa, Ewe Mwenye Ukuu na Heshima.", "Mara baada ya salamu.", "Mtume ﷺ aliyasoma haya baada ya kila swala ya faradhi."),
        "dua_after_salah_help_dhikr" to DuaText("Nisaidie Nikukumbuke", "Ewe Mwenyezi Mungu nisaidie nikukumbuke, nikushukuru na kukuabudu kwa njia iliyo bora.", "Baada ya kila swala - Mtume ﷺ alimusia Mu'adh (RA) aiseme.", "Nasaha maalum ya Mtume ﷺ - ubora na kudumu katika ibada."),
        "dua_sleep_tasbeeh" to DuaText("Tasbeeh-e-Fatimi kabla ya Kulala", "Ametakasika Mwenyezi Mungu (33), sifa njema zote ni za Mwenyezi Mungu (33), Mwenyezi Mungu ni Mkuu (34).", "Kabla ya kulala - Mtume ﷺ aliwafundisha Fatimah na Ali (RA).", "Mtume ﷺ amesema ni bora kwako kuliko mja."),
        "dua_sleep_qina_adhab" to DuaText("Kinga dhidi ya Adhabu", "Ewe Mwenyezi Mungu nilinde na adhabu Yako Siku Utakapowafufua waja wako.", "Mara tatu, na mkono wa kulia umewekwa chini ya shavu.", "Hugeuza usingizi kuwa ukumbusho wa mauti na maandalizi ya Akhera."),
        "dua_bad_dream" to DuaText("Baada ya Ndoto Mbaya", "Najikinga kwa Mwenyezi Mungu na Shet'ani aliyelaaniwa.", "Baada ya ndoto mbaya: kavu-mate kidogo kushoto mara tatu, kisha ugeuke upande mwingine.", "Ndoto mbaya haitakudhuru; usimwambie mtu yeyote kuhusu hilo."),
        "dua_ya_hayyu_ya_qayyum" to DuaText("Ya Hayyu Ya Qayyum", "Ewe Uliye Hai, Ewe Mlinzi wa yote! Kwa rehema zako natafuta msaada.", "Jambo linapokuwa zito sana.", "Kila jambo lilipomsumbua Mtume ﷺ, alikuwa akisema hivi."),
        "dua_entering_market" to DuaText("Kuingia Sokoni", "Hapana apasae kuabudiwa kwa haki isipokuwa Mwenyezi Mungu, peke yake, asiye na mshirika. Ufalme ni wake na sifa njema ni zake. Anahuisha na anafisha, na Yeye yu hai na hafi. Mkononi mwake mna kheri zote, na Yeye ni Muweza wa kila kitu.", "Wakati wa kuingia sokoni.", "Hadithi inataja malipo makubwa kwa ajili yake (milioni ya wema)."),
        "dua_adam_forgiveness" to DuaText("Dua ya Mtume Adam (AS)", "Mola wetu Mlezi tumejidhulumu nafsi zetu, na usipotusamehe na ukaturehemu, bila shaka tutakuwa miongoni mwa waliokhasirika.", "Dua ya toba ya Adam na Hawwa (AS).", "Toba ya kwanza ya wanadamu - Mwenyezi Mungu aliikubali."),
        "dua_abu_bakr" to DuaText("Dua alimfundisha Abu Bakr (RA)", "Ewe Mwenyezi Mungu, nimejidhulumu sana nafsi yangu, na hakuna anayesamehe dhambi ila Wewe, basi nipe msamaha kutoka kwako na unirehemu. Hakika Wewe ni Mwenye kusamehe, Mwenye kurehemu.", "Mtume ﷺ alimfundisha Abu Bakr as-Siddiq (RA) kusema katika sala (baada ya tashahhud).", "Dua ya Sunnah kwa mwisho wa swala."),
        "dua_astaghfirullah_atubu" to DuaText("Istighfar ya kila siku", "Naomba msamaha kwa Mwenyezi Mungu na ninatubia kwake.", "Mtume ﷺ aliomba msamaha zaidi ya mara sabini kwa siku.", "Mtume ﷺ amesema: Mimi namuomba Mwenyezi Mungu msamaha na ninatubia Kwake zaidi ya mara sabini kwa siku."),
        "dua_laylatul_qadr" to DuaText("Dua kwa Laylatul-Qadr", "Ewe Mwenyezi Mungu, Wewe ni Mwingi wa kusamehe na unapenda kusamehe, basi nisamehe.", "Alifundishwa kwa Aisha (RA) kwa Laylat al-Qadr.", "Dua maalum kwa mikesha ya mwisho ya Ramadhani na Laylatul-Qadr."),
        "dua_family_coolness" to DuaText("Ubaridi wa Macho (Mke na Watoto)", "Mola wetu Mlezi, tujaalie kutoka kwa wake zetu na dhuria zetu ubaridi wa macho yetu, na utujaalie kuwa viongozi wa watu wema.", "Dua ya Qur'an kwa wanandoa na watoto wema.", "Kwa amani nyumbani na watoto wenye haki."),
        "dua_righteous_children" to DuaText("Kwa Wazao Wenye Haki", "Mola wangu Mlezi, nipe dhuria kutoka kwako. Hakika Wewe ni Mwenye kusikia maombi.", "Dua ya Mtume Zakariya (AS).", "Dua ya Quran kwa wale wanaotafuta watoto."),
        "dua_ibrahim_prayer_family" to DuaText("Waanzilishi wa Maombi", "Mola wangu Mlezi, nijaalie niwe mwenye kusimamisha Swalah, na katika kizazi changu. Mola wetu Mlezi, nikubalie dua yangu. Mola wetu Mlezi, nighufirie mimi na wazazi wangu wawili na Waumini Siku yatakayo wekwa hisabu.", "Dua ya Nabii Ibrahim (AS) kwa ajili yake na kizazi chake.", "Kawaida husomwa mwishoni mwa sala."),
        "dua_newlywed" to DuaText("Hongera Wanaooa Wapya", "Mwenyezi Mungu akubariki, akuletee baraka na akulete nyinyi wawili katika wema.", "Wakati wa kumpongeza mtu kwenye ndoa yake.", "Pongezi za Sunnah kwa ndoa."),
        "dua_before_eating" to DuaText("Kabla ya Kula", "Kwa jina la Mwenyezi Mungu. (Ikisahauliwa:) Kwa jina la Mwenyezi Mungu, mwanzo wake na mwisho wake.", "Kabla ya kula. Ukisahau, sema kidogo.", "Kusema Bismillah kunamzuia Shaytan asishiriki chakula."),
        "dua_after_eating" to DuaText("Baada ya Kula", "Sifa njema zote ni za Mwenyezi Mungu aliyenilisha haya na akaniruzuku bila ya uwezo wala uwezo wowote kwa upande wangu.", "Baada ya kumaliza chakula.", "Dhambi zilizopita za yule anayesema zimesamehewa."),
        "dua_host" to DuaText("Kwa Mwenyeji", "Ewe Mwenyezi Mungu wabariki katika ulichowaruzuku, wasamehe na uwarehemu.", "Kwa mwenyeji, baada ya kula nyumbani kwa mtu.", "Kumshukuru mwenyeji kwa njia ya Sunnah."),
        "dua_breaking_fast" to DuaText("Baada ya Kufunga Saumu", "Kiu imekwisha, mishipa imelowa, na malipo yamethibiti, ikiwa Mwenyezi Mungu anataka.", "Wakati wa iftar.", "Mtume ﷺ alisema haya wakati wa kufuturu."),
        "dua_new_clothes" to DuaText("Kuvaa Nguo Mpya", "Ewe Mwenyezi Mungu, sifa zote ni Zako; Umenivika hivi. Ninakuomba kheri yake na kheri ya yale iliyoumbiwa, na najikinga Kwako kutokana na shari yake na ubaya wa yale ambayo ilifanyiwa.", "Wakati wa kuvaa vazi jipya (kuipa jina, kama vile shati au kilemba).", "Mtume ﷺ alifanya dua hii akiwa amevaa vazi jipya. (Dua ya kila siku ya kuvaa iko chini ya 'Kuvaa'.)"),
        "dua_rabbana_atina" to DuaText("Wema katika Dunia na Akhera", "Mola wetu Mlezi, tupe mema duniani na Akhera mema, na utulinde na adhabu ya Moto.", "Dua aliyoifanya Mtume ﷺ mara nyingi zaidi.", "Dua inayokusanya kila kheri ya dunia na Akhera."),
        "dua_rabbi_zidni_ilma" to DuaText("Kuongezeka kwa Maarifa", "Mola wangu Mlezi nizidishie ilimu.", "Kwa kuongezeka kwa maarifa.", "Mwenyezi Mungu alimwamrisha Mtume ﷺ asiombe kuzidishiwa ila elimu tu."),
        "dua_musa_sharh_sadr" to DuaText("Ufunguzi wa Kifua (Musa AS)", "Mola wangu Mlezi, nikunjulie kifua changu, na unifanyie wepesi kazi yangu, na lifungue fundo lililo katika ulimi wangu ili wapate kuelewa kauli yangu.", "Kabla ya mtihani, hotuba au kazi yoyote ngumu.", "Dua ya Nabii Musa (AS) - utulivu wa moyo na wepesi katika kazi ya mtu."),
        "dua_la_tuzigh" to DuaText("Uthabiti wa Moyo", "Mola wetu Mlezi, usizipotoe nyoyo zetu baada ya wewe kutuongoza, na utupe rehema kutoka kwako. Hakika Wewe ndiye Mpaji.", "Kwa uthabiti juu ya uwongofu.", "Dua ya kubaki imara katika imani."),
        "dua_ya_muqallib" to DuaText("Ewe Mgeuza Mioyo", "Ewe Mwenye kugeuza nyoyo, uimarishe moyo wangu juu ya dini yako.", "Mtume ﷺ mara nyingi alifanya dua hii.", "Kwa mujibu wa Umm Salamah (RA), dua Mtume ﷺ aliifanya mara nyingi zaidi."),
        "dua_la_tuakhidhna" to DuaText("Aya za Mwisho za Surah Al-Baqarah", "Mola wetu Mlezi, usituchukulie tukisahau au tukakosea. Mola wetu Mlezi, usituwekee mzigo kama ule uliowatwisha waliokuwa kabla yetu. Mola wetu Mlezi, usitutwike tusioweza kustahimili. Utusamehe, utusamehe na utuhurumie. Wewe ndiye Mlinzi wetu, basi tusaidie dhidi ya watu makafiri.", "Usiku kabla ya kulala - aya mbili za mwisho za Surah al-Baqarah.", "Yeyote anayesoma aya mbili za mwisho za Surah al-Baqarah usiku, zitamtosha."),
        "dua_visiting_sick" to DuaText("Kuwatembelea Wagonjwa", "Namuomba Mwenyezi Mungu Mtukufu, Mola Mlezi wa Arshi Kuu, akuponye.", "Mara saba wakati wa kutembelea wagonjwa.", "Ikiwa wakati wa kufa haujafika, Mwenyezi Mungu atamponya."),
        "dua_ruqyah_pain" to DuaText("Kwa Maumivu ya Mwili", "Najikinga kwa Mwenyezi Mungu na uweza wake kutokana na shari ya ninayoyahisi na ninayoyaogopa.", "Weka mkono wako pale inapouma, sema Bismillah mara tatu, kisha dua hii mara saba.", "Mtume ﷺ alimfundisha Uthman ibn Abil-'As (RA) kwa ajili ya maumivu."),
        "dua_ruqyah_nabawi" to DuaText("Ruqyah ya kinabii kwa wagonjwa", "Ewe Mwenyezi Mungu, Mola wa watu! Ondosha madhara na upe tiba, kwani Wewe ndiye unayeponya; hakuna tiba ila tiba Yako - tiba isiyoachi ugonjwa nyuma.", "Huku akipitisha mkono juu ya mgonjwa.", "Mtume ﷺ alikariri haya alipokuwa akiwatembelea watu wa familia yake wagonjwa."),
        "dua_kalimat_tammat" to DuaText("Kutafuta Kimbilio kwa Maneno Kamilifu", "Najikinga na maneno ya Mwenyezi Mungu yaliyo kamili kutokana na shari ya vile alivyoviumba.", "Wakati wa kusimama mahali, au jioni.", "Atakayesimama mahali na kusema hivi, hakuna kitakachomdhuru mpaka aondoke."),
        "dua_evil_eye" to DuaText("Ulinzi kwa Watoto (Jicho Ovu)", "Nakuombeni ulinzi kwa maneno kamili ya Mwenyezi Mungu kutoka kwa kila shetani na kila kiumbe chenye sumu, na kila jicho lenye madhara.", "Mtume ﷺ aliisoma hii juu ya Hasan na Husein (RA).", "Dua ya Sunnah ya kuwalinda watoto kutokana na jicho baya na madhara (kwa mtoto mmoja sema 'U'īdhuka')."),
        "dua_seeing_afflicted" to DuaText("Kuona Mtu Katika Kesi", "Sifa njema zote ni za Mwenyezi Mungu ambaye ameniepusha na yale Aliyokujaribuni kwayo, na amenifadhilisha juu ya mengi ya viumbe Vyake.", "Unapomwona mtu kwenye kesi (sema mwenyewe kimya kimya).", "Yule anayesema imehifadhiwa salama kutokana na kesi hiyo."),
        "dua_istikhara" to DuaText("Salat al-Istikhara", "Ewe Mwenyezi Mungu, mimi natafuta kheri kwa ujuzi wako, natafuta uwezo kwa uwezo wako, na nakuomba fadhila zako kubwa. Wewe una uwezo na mimi sina; Unajua na mimi sijui, na Wewe ndiye Mjuzi wa ghaibu. Ewe Mwenyezi Mungu, ikiwa kwa ujuzi wako jambo hili (likumbuke) ni kheri kwa dini yangu, maisha yangu na mwisho wangu, basi niandikie mimi, nifanyie wepesi na unibariki humo. Na ikiwa kwa ujuzi Wako jambo hili ni baya kwa dini yangu, maisha yangu na mwisho wangu, basi niepushe nayo na uniepushe nayo, na uniwekee kheri popote ilipo, basi niridhishe nayo.", "Baada ya rakaa mbili za swala ya hiari, kutafuta lililo bora katika jambo linaloruhusiwa.", "Mtume ﷺ aliwafundisha Maswahaba istikhara katika mambo yote kama alivyowafundisha surah ya Quran."),
    )
}
